<?php
if (!defined('ABSPATH')) { exit; }
function mdg_alloc_install_file(){return WP_CONTENT_DIR.'/plugins/madagaskar-yonetim-merkezi-v5/includes/class-mdg-v5-finance.php';}
function mdg_alloc_install_new(){return base64_decode('',true);}
function mdg_alloc_install_sha(){return array('bd7a38ec0b8052eed67a6fa0cb3b9f89da2e81feaa9aa6f4d88e0ca5a49bf732','1a8b03fe8349c000f4ce2292581d9b1545fa66cd04f7ea8325dd3661ad56e47f');}
function mdg_alloc_install_stats(){global $wpdb;return $wpdb->get_row("SELECT COUNT(*) AS records, SUM(amount) AS total, SUM(CRC32(CONCAT_WS('|',id,event_id,scope,amount,expense_date,category,description,notes))) AS fingerprint FROM ".$wpdb->prefix."mdg_v5_expenses",ARRAY_A);}
add_action('admin_menu',function(){add_submenu_page('tools.php','Ortak Gider Kurulumu','Ortak Gider Kurulumu','manage_options','mdg-allocation-install',function(){
if(!current_user_can('manage_options'))return;
$p=mdg_alloc_install_file();$sha=is_file($p)?hash_file('sha256',$p):'missing';$hashes=mdg_alloc_install_sha();
echo '<div class="wrap"><h1>Ortak Gider Kurulumu</h1><p>Canlı kaynak SHA256: <code>'.esc_html($sha).'</code></p><p>'.($sha===$hashes[1]?'Kurulum doğrulandı':($sha===$hashes[0]?'Kaynak eşleşti — hazır':'Kaynak farklı — durduruldu')).'</p><pre>'.esc_html(wp_json_encode(mdg_alloc_install_stats())).'</pre>';
if($sha===$hashes[0]){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="mdg_allocation_install">';wp_nonce_field('mdg_allocation_install');echo '<button class="button button-primary">Yedek Al ve Ortak Gider Ekranını Güncelle</button></form>';}
if($sha===$hashes[1]){echo '<pre>'.esc_html(wp_json_encode(get_option('mdg_alloc_install_evidence_20261009'))).'</pre>';}
echo '</div>';
});});
add_action('admin_post_mdg_allocation_install',function(){
if(!current_user_can('manage_options'))wp_die('Yetkiniz yok.');check_admin_referer('mdg_allocation_install');
$p=mdg_alloc_install_file();$hashes=mdg_alloc_install_sha();$old=file_get_contents($p);
if(hash('sha256',$old)!==$hashes[0])wp_die('Kaynak değişmiş, durduruldu.');
$new=mdg_alloc_install_new();if(hash('sha256',$new)!==$hashes[1])wp_die('Paket doğrulanamadı.');
if(!get_option('mdg_alloc_install_backup_20261009')&&!add_option('mdg_alloc_install_backup_20261009',base64_encode($old),'','no'))wp_die('Yedek alınamadı.');
$before=mdg_alloc_install_stats();
if(file_put_contents($p,$new,LOCK_EX)!==strlen($new)||hash_file('sha256',$p)!==$hashes[1]){file_put_contents($p,$old,LOCK_EX);wp_die('Dosya yazımı doğrulanamadı, geri alındı.');}
if(function_exists('opcache_invalidate'))opcache_invalidate($p,true);
update_option('mdg_alloc_install_evidence_20261009',array('before'=>$before,'after'=>mdg_alloc_install_stats(),'sha256'=>$hashes[1],'time'=>current_time('mysql')),false);
wp_safe_redirect(admin_url('tools.php?page=mdg-allocation-install'));exit;
});
